// 1. Ambil payload dari Webhook
const raw = $input.first().json;
const payload = raw.body || raw;

const assetCode = payload.asset_code || '-';
const assetName = payload.asset_name || '-';
const location = payload.location || '-';
const ipAddress = payload.ip_address || '-';
const type = (payload.type || 'offline').toLowerCase();
const severity = (payload.severity || 'critical').toUpperCase();

// 2. Logika Anti-Spam (Intelligent Cooldown Buffer)
// Mencegah flooding / spamming di grup Telegram & Email saat perangkat mengalami pemadaman persisten (mati lama),
// tanpa menyebabkan bug permanent lockout (status terkunci mati selamanya).
const staticData = $getWorkflowStaticData('global');
const COOLDOWN_MS = 10 * 60 * 1000; // Cooldown 10 menit per aset
const now = Date.now();
const lastSent = staticData[`last_sent_${assetCode}`] || 0;

// Jika payload bukan manual force-test dan pengiriman terakhir belum lewat 10 menit, hentikan alur
if (!payload.force && (now - lastSent < COOLDOWN_MS)) {
  return []; // Hentikan eksekusi secara graceful (anti-spam)
}

// Catat waktu pengiriman sukses dan status terakhir
staticData[`last_sent_${assetCode}`] = now;
staticData[`last_status_${assetCode}`] = type;

// 3. Format Waktu Indonesia (WIB)
let timeFormatted = payload.timestamp || payload.last_seen || '-';
if (timeFormatted !== '-') {
  try {
    timeFormatted = new Date(timeFormatted).toLocaleString('id-ID', {
      timeZone: 'Asia/Jakarta', dateStyle: 'medium', timeStyle: 'short'
    }) + ' WIB';
  } catch (e) {}
}

// 4. Ekstrak Symptoms
let symptomText = "Tidak ada data gejala spesifik.";
if (payload.symptoms) {
  if (typeof payload.symptoms === 'object') {
    const ping = payload.symptoms.ping_latency ? `Latensi ${payload.symptoms.ping_latency}` : '';
    const loss = payload.symptoms.packet_loss ? `Packet Loss ${payload.symptoms.packet_loss}` : '';
    symptomText = [ping, loss].filter(Boolean).join(' | ') || JSON.stringify(payload.symptoms);
  } else {
    symptomText = String(payload.symptoms);
  }
}

// 5. Knowledge Base SOP 19 Aset T-AIMS
const sopDatabase = {
  "SRV-01": "Server Utama Data Center. Cek iDRAC/IPMI port 443, utilisasi RAM/CPU, disk root (/), dan restart daemon mariadb/taims-backend. SLA < 15 Menit.",
  "SWM-01": "Core Switch Cisco Catalyst. Cek kabel uplink trunking SFP, modul PoE overheat, dan indikator loop broadcast storm. SLA < 15 Menit.",
  "MKRT-02": "Core Router Data Center. Akses Winbox via MAC, cek route BGP/OSPF, dan beban CPU RouterOS. SLA < 20 Menit.",
  "CLOUD-01": "Cloud VPS Instance. Cek reverse proxy Nginx, daemon PM2, dan akses SSH port 2222. SLA < 15 Menit.",
  "CAS-01": "Server Otentikasi RADIUS. Cek daemon auth port 1812/UDP dan sertifikat TLS internal. SLA < 30 Menit.",
  "RTR-04": "Router Backup Failover. Cek link ISP cadangan dan interface SFP transceiver. SLA < 1 Jam.",
  "RPI-02": "Sensor Suhu Rak Server. Cek adaptor Type-C 5V, microSD, dan sensor DHT ruangan data center. SLA < 30 Menit.",
  "PC-03": "PC Konsol Operator NOC Data Center. Cek tombol power fisik dan kabel LAN meja kontrol. SLA < 4 Jam.",
  "RTR-01": "Router Utama Head Office. Cek lampu LOS/PON pada modem ISP dan adaptor 12V Mikrotik CCR. SLA < 20 Menit.",
  "RPI-01": "Edge Gateway Head Office. Cek status daemon 'systemctl status taims-monitoring' dan kartu microSD. SLA < 30 Menit.",
  "CCTV-01": "CCTV Gerbang Head Office. Cek kabel UTP outdoor, injektor PoE switch, dan lampu infra merah malam. SLA < 45 Menit.",
  "ESP-01": "Sensor Panel Surya & UPS HO. Cek tegangan baterai (< 3.3V) dan sinyal Wi-Fi 2.4GHz. SLA < 1 Jam.",
  "PC-01": "PC Staff Operasional 01. Konfirmasi ke user ruangan apakah PC dimatikan setelah jam kerja. SLA < 4 Jam.",
  "PC-02": "Workstation NOC 02 Control Room. Cek port ethernet belakang casing PC ruang kontrol. SLA < 1 Jam.",
  "SMTV-01": "Smart TV Display Signage. Nyalakan TV via remote dan pastikan koneksi Wi-Fi display aktif. SLA < 4 Jam.",
  "RTR-03": "Core Router TP-Link Multi-WAN Marketing. Cek link WAN ISP dan tunnel VPN ke Head Office. SLA < 20 Menit.",
  "MKRT-01": "Mikrotik Bandwidth Marketing. Akses Winbox, cek CPU load akibat streaming/antrean bandwidth. SLA < 30 Menit.",
  "RTR-02": "Sub-Router Wi-Fi Lt 2 Marketing. Cek kabel LAN uplink dari lantai 1 ke lantai 2. SLA < 1 Jam.",
  "CCTV-02": "CCTV Lobby Marketing. Cek jack adaptor 12V dan link port switch kamera depan. SLA < 45 Menit."
};

const sopSpesifik = sopDatabase[assetCode] || "Lakukan pengecekan konektivitas kabel jaringan dan status catu daya perangkat.";

// 6. Susun Prompt AI
let promptAI = "";
let emoji = "🔴";
let headerFallback = "ALERT";

if (type === 'warning') {
  emoji = "🟡";
  headerFallback = "WARNING: POTENSI GANGGUAN";
  promptAI = `Kamu adalah AI Network Analyst untuk T-AIMS.
Perangkat: ${assetName} (${assetCode})
Lokasi: ${location} | IP: ${ipAddress}
Status: WARNING (Early Warning)
Gejala: ${symptomText}
SOP Acuan: ${sopSpesifik}

Tugasmu: Berikan analisis prediktif dan tindakan pencegahan.
Gunakan format WAJIB ini (teks biasa, bukan JSON):
🟡 [T-AIMS WARNING] POTENSI GANGGUAN TERDETEKSI
━━━━━━━━━━━━━━━━━━━━
📌 Aset: ${assetName} (${assetCode})
🏢 Lokasi: ${location} | 🌐 IP: ${ipAddress}
⚠️ Severity: WARNING (Early Warning)
📊 Gejala: ${symptomText}

🔍 Analisis Prediktif AI (Gemini):
[Jelaskan potensi penyebab sebelum alat mati total]

🛠️ Tindakan Pencegahan Teknisi:
[1 langkah preventif sebelum down total]
━━━━━━━━━━━━━━━━━━━━
Bot: @taims_alert_arik_bot • n8n Early Warning Engine`;

} else {
  emoji = "🔴";
  headerFallback = "OFFLINE ALERT";
  promptAI = `Kamu adalah AI Network Analyst untuk T-AIMS.
Perangkat: ${assetName} (${assetCode})
Lokasi: ${location} | IP: ${ipAddress}
Status: CRITICAL (Offline)
SOP Acuan: ${sopSpesifik}

Tugasmu: Berikan analisis root cause dan SOP penanganan.
Gunakan format WAJIB ini (teks biasa, bukan JSON):
🔴 [T-AIMS ALERT] PERANGKAT DOWN / OFFLINE
━━━━━━━━━━━━━━━━━━━━
📌 Aset: ${assetName} (${assetCode})
🏢 Lokasi: ${location} | 🌐 IP: ${ipAddress}
⚠️ Severity: CRITICAL | SLA MTTR: < 30 Menit

🔍 Analisis Root Cause & Dampak:
[Jelaskan akar masalah teknis & dampak operasional kantor]

🛠️ SOP Penanganan Teknisi:
1. Verifikasi: [Langkah remote/ping]
2. Fisik: [Langkah cek kabel/PoE/LED]
3. Solusi: [Tindakan eskalasi/recovery]
━━━━━━━━━━━━━━━━━━━━
Bot: @taims_alert_arik_bot • n8n Incident Engine`;
}

// 7. Pesan Fallback (Jika AI Timeout / Graceful Degradation)
const messageFallback = `${emoji} [T-AIMS ${headerFallback}]
━━━━━━━━━━━━━━━━━━━━
📌 Aset: ${assetName} (${assetCode})
🏢 Lokasi: ${location} | 🌐 IP: ${ipAddress}
⚠️ Severity: ${severity}
⏰ Waktu: ${timeFormatted}

ℹ️ Notifikasi Standar (AI sedang limit/down)
━━━━━━━━━━━━━━━━━━━━
Bot: @taims_alert_arik_bot • n8n Engine`;

// 8. Return Data Lengkap (Semua Properti Termasuk asset_name)
return {
  json: {
    asset_code: assetCode,
    asset_name: assetName,
    category: payload.category || '-',
    location: location,
    ip_address: ipAddress,
    severity: severity,
    type: type,
    timestamp: timeFormatted,
    symptoms: symptomText,
    message: messageFallback,
    prompt_ai: promptAI
  }
};
